const TARGET_IDS = new Set(SOURCE_UNITMC_SKIN_TARGETS.map(({ character }) => character));

export function tutorialSkinAssetPath(character, skinFrame) {
  if (!TARGET_IDS.has(character)) throw new Error(`Character ${character} is not a UnitMC skin child sprite`);
  if (!Number.isInteger(skinFrame) || skinFrame < 1) throw new Error(`Invalid UnitMC skin frame: ${skinFrame}`);
  return `./public/assets/original-swf/unit-skins/DefineSprite_${character}/${skinFrame}.png`;
}
